40	        public class RowPointers
41	        {
42	            public int ClientRow = 1;  // Sheet 1: AI_OCR ENABLED CLIENT LIST
43	            public int JobRow = 1;  // Sheet 2: AI_OCR DAILY JOB COUNT DETAILS
44	            public int TotalJobRow = 1;  // Sheet 3: AI_OCR TOTAL JOB DETAILS
45	            public int FormatRow = 1;  // Sheet 4: AI_OCR TOTAL FORMAT DETAILS
46	        }
