48	        static async Task Main(string[] args)
49	        {
50	            bool isDryRun = args.Any(a =>
51	                string.Equals(a, "--dry-run", StringComparison.OrdinalIgnoreCase));
52	
53	            try
54	            {
55	                Logger.Info("🚀 AI OCR Daily Report Scheduler started.");
56	                RowPointers rows = new RowPointers();
57	
58	                var builder = new ConfigurationBuilder()
59	                    .SetBasePath(AppContext.BaseDirectory)
60	                    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);
61	
62	                IConfiguration config = builder.Build();
63	                _smtpSettings = config.GetSection("SmtpSettings").Get<SmtpSettings>();
64	                _serverDict = config.GetSection("server_ip_list").Get<Dictionary<string, string>>();
65	                ReportFolder = config.GetSection("ReportSettings:ReportFolder").Value;
66	
67	                if (!Directory.Exists(ReportFolder))
68	                    Directory.CreateDirectory(ReportFolder);
69	
70	                //Logger.Info("======================================================");
71	                Logger.Info("AI OCR Daily Report — run started ({0} server(s) configured)", _serverDict.Count);
72	                //Logger.Info("======================================================");
73	
74	                using var workbook = new XLWorkbook();
75	                {
76	                    // ── 4 Sheets ──────────────────────────────────────────────
77	                    var wsClient = workbook.Worksheets.Add("AI_OCR ENABLED CLIENT LIST");
78	                    var wsJob = workbook.Worksheets.Add("AI_OCR DAILY JOB COUNT DETAILS");
79	                    var wsTotalJob = workbook.Worksheets.Add("AI_OCR TOTAL JOB DETAILS");
80	                    var wsFormat = workbook.Worksheets.Add("AI_OCR TOTAL FORMAT DETAILS");
81	
82	                    int serverIndex = 0;
83	                    foreach (var kvp in _serverDict)
84	                    {
85	                        serverIndex++;
86	                        string serverName = kvp.Key;
87	                        string serverIp = kvp.Value;
88	
89	                        Logger.Info("------------------------------------------------------");
90	                        Logger.Info("[🌐 Connecting to Server: {0}/{1}] START  -> Name: {2}  |  IP: {3}",
91	                            serverIndex, _serverDict.Count, serverName, serverIp);
92	                        Logger.Info("------------------------------------------------------");
93	                        Logger.Info("✅ Connected successfully.");
94	                        // Admin DB connection — same pattern as IRN
95	                        //string connString = $"Server={serverIp};database=ADMIN_IMPEX;uid=rtsadmin;pwd=adminrts@#12345@#rtsadmin;TrustServerCertificate=True;";
96	                        string connString = $"Server={serverIp};database=ImpexLogin;uid=sa;pwd=SA,123;TrustServerCertificate=True;";
97	
98	                        await GetOcrDataList(
99	                            connString, wsClient, wsJob, wsTotalJob, wsFormat,
100	                            serverName, rows);
101	
102	                        Logger.Info("[Server {0}/{1}] FINISHED -> {2} — all client data collected.",
103	                            serverIndex, _serverDict.Count, serverName);
104	
105	                        if (serverIndex < _serverDict.Count)
106	                            Logger.Info("Moving to next server...");
107	                    }
108	
109	                    //Logger.Info("======================================================");
110	                    Logger.Info("All {0} server(s) processed.", _serverDict.Count);
111	                    //Logger.Info("======================================================");
112	
113	                    Logger.Info("📄Building Excel report...");
114	                    // ── Style all 4 sheets ────────────────────────────────────
115	                    StyleSheet(wsClient, "AI_OCR ENABLED CLIENT LIST", rows.ClientRow - 1, 7);
116	                    StyleSheet(wsJob, "AI_OCR DAILY JOB COUNT DETAILS", rows.JobRow - 1, -1);
117	                    StyleSheet(wsTotalJob, "AI_OCR TOTAL JOB DETAILS", rows.TotalJobRow - 1, 16);
118	                    StyleSheet(wsFormat, "AI_OCR TOTAL FORMAT DETAILS", rows.FormatRow - 1, 13);
119	
120	                    fileName = $"AI_OCR_Report_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
121	                    savePath = Path.Combine(ReportFolder, fileName);
122	                    workbook.SaveAs(savePath);
123	                    Logger.Info("Excel report saved: {0}", savePath);
124	                }
125	
126	                if (isDryRun)
127	                {
128	                    Logger.Info("Dry run mode — email NOT sent. Report available at: {0}", savePath);
129	                    Logger.Info("======================================================");
130	                    Logger.Info("Run complete (dry run).");
131	                    Logger.Info("======================================================");
132	                    return;
133	                }
134	
135	                //Logger.Info("Sending report by email...");
136	                await SendEmailWithAttachment(savePath);
137	                Logger.Info("✅ Email sent successfully.");
138	
139	                if (File.Exists(savePath))
140	                {
141	                    File.Delete(savePath);
142	                    Logger.Info("Deleted report after emailing: {0}", fileName);
143	                }
144	
145	                //Logger.Info("======================================================");
146	                Logger.Info("Run complete.");
147	                //Logger.Info("======================================================");
148	            }
149	            catch (Exception ex)
150	            {
151	                Logger.Error(ex, "Run failed with an unhandled error");
152	            }
153	        }
154	
155	        // ─────────────────────────────────────────────────────────────────────
156	        // Main data fetch per server
157	        // ─────────────────────────────────────────────────────────────────────
158	        private static async Task GetOcrDataList(
159	            string connString,
160	            IXLWorksheet wsClient,
161	            IXLWorksheet wsJob,
162	            IXLWorksheet wsTotalJob,
163	            IXLWorksheet wsFormat,
164	            string serverName,
165	            RowPointers rows)
166	        {
167	            await Task.Run(() =>
168	            {
169	                DataSet adminData;
170	                try
171	                {
172	                    adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
173	                }
174	                catch (Exception ex)
175	                {
176	                    Logger.Error(ex, "[{0}] Could not reach the admin database — skipping this server", serverName);
177	                    return;
178	                }
179	
180	                if (adminData == null || adminData.Tables.Count < 2)
181	                {
182	                    Logger.Warn("[{0}] Admin procedure returned no data — skipping this server", serverName);
183	                    return;
184	                }
185	
186	                DataTable clientList = adminData.Tables[0];
187	                DataTable serverList = adminData.Tables[1];
188	
189	                Logger.Info("[{0}] Enabled clients found: {1}  |  Company/database rows: {2}",
190	                    serverName, clientList.Rows.Count, serverList.Rows.Count);
191	
192	                // ── Sheet 1 ───────────────────────────────────────────────────
193	                AppendDataTable(wsClient, clientList, ref rows.ClientRow);
194	
195	                // ── Deduplicate by COMPANY_LICENSE ────────────────────────────
196	                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
197	                var uniqueServers = serverList.AsEnumerable()
198	                    .Where(r => seen.Add(r["COMPANY_LICENSE"].ToString().Trim()))
199	                    .ToList();
200	
201	                Logger.Info("[{0}] Unique companies to process: {1}", serverName, uniqueServers.Count);
202	
203	                int clientIndex = 0;
204	                foreach (DataRow server in uniqueServers)
205	                {
206	                    clientIndex++;
207	                    string workingPeriod = server["WORKING_PERIOD"].ToString();
208	                    string companyLicense = server["COMPANY_LICENSE"].ToString();
209	                    string companyName = server["COMPANY_NAME"].ToString();
210	                    string clientConn = server["CON_STRING"].ToString();
211	
212	                    string enabledDate = ParseDateToYMD(server["ENABLED_ON"].ToString());
213	                    string disabledDate = string.IsNullOrWhiteSpace(
214	                                             server["DISABLED_ON"].ToString())
215	                                         ? ""
216	                                         : ParseDateToYMD(server["DISABLED_ON"].ToString());
217	
218	                    Logger.Info("  [{0}] Client {1}/{2} -> {3} ({4}): fetching data...",
219	                        serverName, clientIndex, uniqueServers.Count, companyLicense, companyName);
220	
221	                    // ── Sheet 2: JOB_COUNT (daily breakdown) ──────────────────
222	                    DataTable jobData = GetClientData(
223	                        clientConn, "JOB_COUNT",
224	                        serverName, workingPeriod, companyLicense,
225	                        companyName, enabledDate, disabledDate);
226	                    AppendDataTable(wsJob, jobData, ref rows.JobRow);
227	
228	                    // ── Sheet 3: TOTAL_JOB_DETAILS (overall summary) ──────────
229	                    DataTable totalJobData = GetClientData(
230	                        clientConn, "TOTAL_JOB_DETAILS",
231	                        serverName, workingPeriod, companyLicense,
232	                        companyName, enabledDate, disabledDate);
233	                    AppendDataTable(wsTotalJob, totalJobData, ref rows.TotalJobRow);
234	
235	                    // ── Sheet 4: FORMAT_COUNT (format details) ────────────────
236	                    DataTable formatData = GetClientData(
237	                        clientConn, "FORMAT_COUNT",
238	                        serverName, workingPeriod, companyLicense,
239	                        companyName, enabledDate, disabledDate);
240	                    AppendDataTable(wsFormat, formatData, ref rows.FormatRow);
241	
242	                    Logger.Info("  [{0}] Client {1}/{2} -> {3} done. Job rows: {4}, TotalJob rows: {5}, Format rows: {6}",
243	                        serverName, clientIndex, uniqueServers.Count, companyLicense,
244	                        jobData.Rows.Count, totalJobData.Rows.Count, formatData.Rows.Count);
245	                }
246	            });
247	        }
