249	        // ─────────────────────────────────────────────────────────────────────
250	        // Admin SP — OCR_AI_ENABLED_COUNT
251	        // ─────────────────────────────────────────────────────────────────────
252	        private static DataSet GetAdminData(
253	            string connString, string flag, string serverName)
254	        {
255	            using var con = new SqlConnection(connString);
256	            using var cmd = new SqlCommand("OCR_AI_ENABLED_COUNT", con)
257	            {
258	                CommandType = CommandType.StoredProcedure,
259	                CommandTimeout = 120
260	            };
261	
262	            cmd.Parameters.AddWithValue("@MFLAG", flag);
263	            cmd.Parameters.AddWithValue("@serverName", serverName);
264	
265	            var errParam = new SqlParameter("@ERRORMSG",
266	                System.Data.SqlDbType.NVarChar, -1)
267	            { Direction = ParameterDirection.Output };
268	            cmd.Parameters.Add(errParam);
269	
270	            var adapter = new SqlDataAdapter(cmd);
271	            var ds = new DataSet();
272	            adapter.Fill(ds);
273	
274	            string errMsg = errParam.Value?.ToString();
275	            if (!string.IsNullOrEmpty(errMsg))
276	                Logger.Warn("[{0}] Admin procedure OCR_AI_ENABLED_COUNT reported an error: {1}", serverName, errMsg);
277	
278	            return ds;
279	        }
280	
281	        // ─────────────────────────────────────────────────────────────────────
282	        // Client SP — OCR_AI_JOB_COUNT
283	        // ─────────────────────────────────────────────────────────────────────
284	        private static DataTable GetClientData(
285	            string connStr,
286	            string flag,
287	            string serverName,
288	            string workingPeriod,
289	            string companyLicense,
290	            string companyName,
291	            string enabledDate,
292	            string disabledDate)
293	        {
294	            try
295	            {
296	                using var conn = new SqlConnection(connStr);
297	                using var cmd = new SqlCommand("OCR_AI_JOB_COUNT", conn)
298	                {
299	                    CommandType = CommandType.StoredProcedure,
300	                    CommandTimeout = 180
301	                };
302	
303	                cmd.Parameters.AddWithValue("@MFLAG", flag);
304	                cmd.Parameters.AddWithValue("@Server_name", serverName);
305	                cmd.Parameters.AddWithValue("@WORKING_PERIOD", workingPeriod);
306	                cmd.Parameters.AddWithValue("@COMPANY_LICENSE", companyLicense);
307	                cmd.Parameters.AddWithValue("@COMPANY_NAME", companyName);
308	                cmd.Parameters.AddWithValue("@ENABLED_DATE", enabledDate);
309	                cmd.Parameters.AddWithValue("@DISABLED_DATE", disabledDate);
310	
311	                var errParam = new SqlParameter("@ERRORMSG",
312	                    System.Data.SqlDbType.NVarChar, -1)
313	                { Direction = ParameterDirection.Output };
314	                cmd.Parameters.Add(errParam);
315	
316	                var adapter = new SqlDataAdapter(cmd);
317	                var ds = new DataSet();
318	                adapter.Fill(ds);
319	
320	                string errMsg = errParam.Value?.ToString();
321	                if (!string.IsNullOrEmpty(errMsg))
322	                    Logger.Warn("  [{0}] Client {1} — {2} reported an error: {3}",
323	                        serverName, companyLicense, flag, errMsg);
324	
325	                // JOB_COUNT uses EXEC(@sql) with SET NOCOUNT ON
326	                // → result lands in Tables[0] (no PRINT statement)
327	                return ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
328	            }
329	            catch (SqlException ex)
330	            {
331	                Logger.Error("  [{0}] Client {1} — {2} FAILED: SQL error {3} — {4}. Skipping.",
332	                    serverName, companyLicense, flag, ex.Number, ex.Message);
333	                return new DataTable();
334	            }
335	            catch (Exception ex)
336	            {
337	                Logger.Error(ex, "  [{0}] Client {1} — {2} FAILED",
338	                    serverName, companyLicense, flag);
339	                return new DataTable();
340	            }
341	        }
342	
343	        // ─────────────────────────────────────────────────────────────────────
344	        // Append DataTable to worksheet
345	        // ─────────────────────────────────────────────────────────────────────
346	        private static void AppendDataTable(
347	            IXLWorksheet ws, DataTable table, ref int currentRow)
348	        {
349	            if (table == null || table.Rows.Count == 0) return;
350	
351	            if (currentRow == 1)
352	            {
353	                for (int col = 0; col < table.Columns.Count; col++)
354	                {
355	                    var cell = ws.Cell(currentRow, col + 1);
356	                    cell.Value = table.Columns[col].ColumnName;
357	                    cell.Style.Font.Bold = true;
358	                    cell.Style.Fill.BackgroundColor = XLColor.DarkBlue;
359	                    cell.Style.Font.FontColor = XLColor.White;
360	                    cell.Style.Alignment.Horizontal =
361	                        XLAlignmentHorizontalValues.Center;
362	                }
363	                currentRow++;
364	            }
365	
366	            foreach (DataRow row in table.Rows)
367	            {
368	                for (int col = 0; col < table.Columns.Count; col++)
369	                    ws.Cell(currentRow, col + 1).Value = row[col]?.ToString();
370	
371	                if (currentRow % 2 == 0)
372	                    ws.Range(currentRow, 1, currentRow, table.Columns.Count)
373	                      .Style.Fill.BackgroundColor = XLColor.LightGray;
374	
375	                currentRow++;
376	            }
377	        }
