379	        // ─────────────────────────────────────────────────────────────────────
380	        // Style sheet
381	        // ─────────────────────────────────────────────────────────────────────
382	        private static void StyleSheet(
383	            IXLWorksheet ws, string title, int lastDataRow, int colCount)
384	        {
385	            try
386	            {
387	                ws.Row(1).InsertRowsAbove(1);
388	                int usedCols = colCount > 0
389	                    ? colCount
390	                    : ws.LastColumnUsed()?.ColumnNumber() ?? 1;
391	
392	                var titleRange = ws.Range(1, 1, 1, usedCols);
393	                titleRange.Merge();
394	                titleRange.FirstCell().Value = title;
395	                titleRange.Style.Font.Bold = true;
396	                titleRange.Style.Font.FontSize = 14;
397	                titleRange.Style.Alignment.Horizontal =
398	                    XLAlignmentHorizontalValues.Center;
399	                titleRange.Style.Fill.BackgroundColor = XLColor.Navy;
400	                titleRange.Style.Font.FontColor = XLColor.White;
401	
402	                ws.SheetView.FreezeRows(2);
403	
404	                if (ws.RangeUsed() != null)
405	                {
406	                    ws.RangeUsed().Style.Border.OutsideBorder =
407	                        XLBorderStyleValues.Thin;
408	                    ws.RangeUsed().Style.Border.InsideBorder =
409	                        XLBorderStyleValues.Thin;
410	                }
411	
412	                ws.Columns().AdjustToContents();
413	            }
414	            catch (Exception ex)
415	            {
416	                Logger.Warn("StyleSheet failed for {0}: {1}", ws.Name, ex.Message);
417	            }
418	        }
419	
420	        // ─────────────────────────────────────────────────────────────────────
421	        // Parse dd-MM-yyyy → yyyy-MM-dd
422	        // ─────────────────────────────────────────────────────────────────────
423	        private static string ParseDateToYMD(string dateStr)
424	        {
425	            if (string.IsNullOrWhiteSpace(dateStr)) return "";
426	            try
427	            {
428	                return DateTime.ParseExact(dateStr.Trim(), "dd-MM-yyyy", null)
429	                               .ToString("yyyy-MM-dd");
430	            }
431	            catch
432	            {
433	                Logger.Warn("Could not parse date: {0}", dateStr);
434	                return dateStr;
435	            }
436	        }
437	
438	        // ─────────────────────────────────────────────────────────────────────
439	        // Send email with Excel attachment
440	        // ─────────────────────────────────────────────────────────────────────
441	        private static async Task SendEmailWithAttachment(string filePath)
442	        {
443	            try
444	            {
445	                Logger.Info("Sending email...");
446	
447	                string reportDate = DateTime.Now.AddDays(-1).ToString("dd-MM-yyyy");
448	                string subject = _smtpSettings.Subject.Replace("{Date}", reportDate);
449	                string htmlBody = _smtpSettings.Body.Replace("{Date}", reportDate);
450	
451	                using var mail = new MailMessage
452	                {
453	                    From = new MailAddress(
454	                                     _smtpSettings.FromEmail,
455	                                     _smtpSettings.Mail_header),
456	                    Subject = subject,
457	                    IsBodyHtml = true
458	                };
459	
460	                string logoPath = Path.Combine(
461	                    AppContext.BaseDirectory, "Assets", "Company_Logo.png");
462	
463	                if (File.Exists(logoPath))
464	                {
465	                    var htmlView = AlternateView.CreateAlternateViewFromString(
466	                        htmlBody, null, "text/html");
467	                    var logoRes = new LinkedResource(logoPath, "image/png")
468	                    { ContentId = "companylogo" };
469	                    htmlView.LinkedResources.Add(logoRes);
470	                    mail.AlternateViews.Add(htmlView);
471	                }
472	                else
473	                {
474	                    Logger.Warn("Logo not found at {0}; sending without logo", logoPath);
475	                    mail.Body = htmlBody;
476	                }
477	
478	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
479	                    mail.To.Add(to.Trim());
480	
481	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
482	                    mail.CC.Add(cc.Trim());
483	
484	                using (var fs = new FileStream(
485	                    filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
486	                {
487	                    mail.Attachments.Add(new Attachment(fs, Path.GetFileName(filePath)));
488	
489	                    using var smtp = new SmtpClient(
490	                        _smtpSettings.Host, _smtpSettings.SmtpPort)
491	                    {
492	                        Credentials = new NetworkCredential(
493	                            _smtpSettings.username, _smtpSettings.password),
494	                        EnableSsl = _smtpSettings.enableSsl
495	                    };
496	                    await smtp.SendMailAsync(mail);
497	                }
498	
499	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
500	
501	                if (File.Exists(filePath))
502	                {
503	                    File.Delete(filePath);
504	                    Logger.Info("Deleted report: {0}", filePath);
505	                }
506	            }
507	            catch (Exception ex)
508	            {
509	                Logger.Error(ex, "Email send failed");
510	            }
511	        }
512	    }
513	}

