1	using ClosedXML.Excel;
2	using Microsoft.Data.SqlClient;
3	using Microsoft.Extensions.Configuration;
4	using NLog;
5	using System.Data;
6	using System.Net;
7	using System.Net.Mail;
8	
9	namespace DSRAutoMailScheduler
10	{
11	    class Program
12	    {
13	        private static readonly Logger Logger = LogManager.GetCurrentClassLogger();
14	        private static SmtpSettings _smtpSettings = null!;
15	        private static Dictionary<string, string> _serverDict = null!;
16	        private static string ReportFolder = null!;
17	        private static string fileName = null!;
18	        private static string savePath = null!;
19	
20	        public class SmtpSettings
21	        {
22	            public string Mail_header { get; set; }
23	            public string Host { get; set; }
24	            public string username { get; set; }
25	            public string password { get; set; }
26	            public int SmtpPort { get; set; }
27	            public bool enableSsl { get; set; }
28	            public string FromEmail { get; set; }
29	            public string[] ToEmails { get; set; }
30	            public string[] CCEmails { get; set; }
31	            public string Subject { get; set; }
32	            public string Body { get; set; }
33	        }
34	
35	        public class RowPointers
36	        {
37	            public int ClientRow = 1;  // Sheet 1: AI_OCR ENABLED CLIENT LIST
38	            public int JobRow = 1;  // Sheet 2: AI_OCR DAILY JOB COUNT DETAILS
39	            public int TotalJobRow = 1;  // Sheet 3: AI_OCR TOTAL JOB DETAILS
40	            public int FormatRow = 1;  // Sheet 4: AI_OCR TOTAL FORMAT DETAILS
41	        }
42	
43	        static async Task Main(string[] args)
44	        {
45	            bool isDryRun = args.Any(a =>
46	                string.Equals(a, "--dry-run", StringComparison.OrdinalIgnoreCase));
47	
48	            try
49	            {
50	                Logger.Info("🚀 AI OCR Daily Report Scheduler started.");
51	                RowPointers rows = new RowPointers();
52	
53	                var builder = new ConfigurationBuilder()
54	                    .SetBasePath(AppContext.BaseDirectory)
55	                    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);
56	
57	                IConfiguration config = builder.Build();
58	                _smtpSettings = config.GetSection("SmtpSettings").Get<SmtpSettings>();
59	                _serverDict = config.GetSection("server_ip_list").Get<Dictionary<string, string>>();
60	                ReportFolder = config.GetSection("ReportSettings:ReportFolder").Value;
61	
62	                if (!Directory.Exists(ReportFolder))
63	                    Directory.CreateDirectory(ReportFolder);
64	
65	                //Logger.Info("======================================================");
66	                Logger.Info("AI OCR Daily Report — run started ({0} server(s) configured)", _serverDict.Count);
67	                //Logger.Info("======================================================");
68	
69	                using var workbook = new XLWorkbook();
70	                {
71	                    // ── 4 Sheets ──────────────────────────────────────────────
72	                    var wsClient = workbook.Worksheets.Add("AI_OCR ENABLED CLIENT LIST");
73	                    var wsJob = workbook.Worksheets.Add("AI_OCR DAILY JOB COUNT DETAILS");
74	                    var wsTotalJob = workbook.Worksheets.Add("AI_OCR TOTAL JOB DETAILS");
75	                    var wsFormat = workbook.Worksheets.Add("AI_OCR TOTAL FORMAT DETAILS");
76	
77	                    int serverIndex = 0;
78	                    foreach (var kvp in _serverDict)
79	                    {
80	                        serverIndex++;
81	                        string serverName = kvp.Key;
82	                        string serverIp = kvp.Value;
83	
84	                        Logger.Info("------------------------------------------------------");
85	                        Logger.Info("[🌐 Connecting to Server: {0}/{1}] START  -> Name: {2}  |  IP: {3}",
86	                            serverIndex, _serverDict.Count, serverName, serverIp);
87	                        Logger.Info("------------------------------------------------------");
88	                        Logger.Info("✅ Connected successfully.");
89	                        // Admin DB connection — same pattern as IRN
90	                        //string connString = $"Server={serverIp};database=ADMIN_IMPEX;uid=rtsadmin;pwd=adminrts@#12345@#rtsadmin;TrustServerCertificate=True;";
91	                        string connString = $"Server={serverIp};database=ImpexLogin;uid=sa;pwd=SA,123;TrustServerCertificate=True;";
92	
93	                        await GetOcrDataList(
94	                            connString, wsClient, wsJob, wsTotalJob, wsFormat,
95	                            serverName, rows);
96	
97	                        Logger.Info("[Server {0}/{1}] FINISHED -> {2} — all client data collected.",
98	                            serverIndex, _serverDict.Count, serverName);
99	
100	                        if (serverIndex < _serverDict.Count)
101	                            Logger.Info("Moving to next server...");
102	                    }
103	
104	                    //Logger.Info("======================================================");
105	                    Logger.Info("All {0} server(s) processed.", _serverDict.Count);
106	                    //Logger.Info("======================================================");
107	
108	                    Logger.Info("📄Building Excel report...");
109	                    // ── Style all 4 sheets ────────────────────────────────────
110	                    StyleSheet(wsClient, "AI_OCR ENABLED CLIENT LIST", rows.ClientRow - 1, 7);
111	                    StyleSheet(wsJob, "AI_OCR DAILY JOB COUNT DETAILS", rows.JobRow - 1, -1);
112	                    StyleSheet(wsTotalJob, "AI_OCR TOTAL JOB DETAILS", rows.TotalJobRow - 1, 16);
113	                    StyleSheet(wsFormat, "AI_OCR TOTAL FORMAT DETAILS", rows.FormatRow - 1, 13);
114	
115	                    fileName = $"AI_OCR_Report_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
116	                    savePath = Path.Combine(ReportFolder, fileName);
117	                    workbook.SaveAs(savePath);
118	                    Logger.Info("Excel report saved: {0}", savePath);
119	                }
120	
121	                if (isDryRun)
122	                {
123	                    Logger.Info("Dry run mode — email NOT sent. Report available at: {0}", savePath);
124	                    Logger.Info("======================================================");
125	                    Logger.Info("Run complete (dry run).");
126	                    Logger.Info("======================================================");
127	                    return;
128	                }
129	
130	                //Logger.Info("Sending report by email...");
131	                await SendEmailWithAttachment(savePath);
132	                Logger.Info("✅ Email sent successfully.");
133	
134	                if (File.Exists(savePath))
135	                {
136	                    File.Delete(savePath);
137	                    Logger.Info("Deleted report after emailing: {0}", fileName);
138	                }
139	
140	                //Logger.Info("======================================================");
141	                Logger.Info("Run complete.");
142	                //Logger.Info("======================================================");
143	            }
144	            catch (Exception ex)
145	            {
146	                Logger.Error(ex, "Run failed with an unhandled error");
147	            }
148	        }
149	
